[CmdletBinding()]
param(
    [string]$RepositoryRoot = (Get-Location).Path,
    [switch]$RunTests,
    [switch]$RunAudit
)

$ErrorActionPreference = "Stop"
$root = (Resolve-Path $RepositoryRoot).Path

if (-not (Test-Path (Join-Path $root ".git"))) {
    throw "La ruta no parece ser la raíz de un repositorio Git: $root"
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root "artifacts\backups\spb-003.2-b1.3\$timestamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

function Write-Utf8File {
    param(
        [Parameter(Mandatory)][string]$RelativePath,
        [Parameter(Mandatory)][string]$Base64Content
    )
    $target = Join-Path $root $RelativePath
    $parent = Split-Path -Parent $target
    New-Item -ItemType Directory -Force -Path $parent | Out-Null

    if (Test-Path $target) {
        $backup = Join-Path $backupRoot $RelativePath
        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $backup) | Out-Null
        Copy-Item $target $backup -Force
    }

    $bytes = [Convert]::FromBase64String($Base64Content)
    [IO.File]::WriteAllBytes($target, $bytes)
    Write-Host "ACTUALIZADO: $RelativePath" -ForegroundColor Cyan
}

Write-Host "Aplicando SPB-003.2-B1.3..." -ForegroundColor Yellow

Write-Utf8File -RelativePath "src/sgoda/pmo/audit/models.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/checks/quality.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/checks/tests_inventory.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/checks/documentation.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/checks/__init__.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/orchestrator.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/audit/reporting/reporters.py" -Base64Content ""
Write-Utf8File -RelativePath "src/sgoda/pmo/closure/closure_orchestrator.py" -Base64Content ""
Write-Utf8File -RelativePath "tests/pmo/audit/test_b1_3_quality.py" -Base64Content ""
Write-Utf8File -RelativePath ".github/workflows/spb-003-2-closure-audit.yml" -Base64Content ""

$manifest = [ordered]@{
    increment = "SPB-003.2-B1.3"
    applied_at = (Get-Date).ToString("o")
    repository_root = $root
    backup_root = $backupRoot
    files = @(

        "src/sgoda/pmo/audit/models.py"
        "src/sgoda/pmo/audit/checks/quality.py"
        "src/sgoda/pmo/audit/checks/tests_inventory.py"
        "src/sgoda/pmo/audit/checks/documentation.py"
        "src/sgoda/pmo/audit/checks/__init__.py"
        "src/sgoda/pmo/audit/orchestrator.py"
        "src/sgoda/pmo/audit/reporting/reporters.py"
        "src/sgoda/pmo/closure/closure_orchestrator.py"
        "tests/pmo/audit/test_b1_3_quality.py"
        ".github/workflows/spb-003-2-closure-audit.yml"
    )
}
$manifestPath = Join-Path $root "artifacts\development\spb-003.2-b1.3\manifest.json"
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $manifestPath) | Out-Null
$manifest | ConvertTo-Json -Depth 5 | Set-Content $manifestPath -Encoding utf8

$env:PYTHONPATH = (Join-Path $root "src")

if ($RunTests) {
    Write-Host "`nEjecutando pruebas PMO..." -ForegroundColor Yellow
    Push-Location $root
    try {
        python -m pytest -q tests/pmo/audit
        if ($LASTEXITCODE -ne 0) {
            throw "Fallaron las pruebas PMO."
        }

        if (Test-Path (Join-Path $root "builder\tests")) {
            Write-Host "`nEjecutando pruebas Builder..." -ForegroundColor Yellow
            Push-Location (Join-Path $root "builder")
            try {
                python -m pytest -q
                if ($LASTEXITCODE -ne 0) {
                    throw "Fallaron las pruebas Builder."
                }
            }
            finally {
                Pop-Location
            }
        }
        else {
            Write-Warning "No existe builder\tests; el Auditor lo reportará como bloqueante."
        }
    }
    finally {
        Pop-Location
    }
}

if ($RunAudit) {
    Write-Host "`nEjecutando Auditor modular..." -ForegroundColor Yellow
    Push-Location $root
    try {
        python -m sgoda.pmo.audit.cli `
          --repository . `
          --output artifacts/audit/spb-003.2
        $auditExit = $LASTEXITCODE
        if ($auditExit -notin @(0, 2)) {
            throw "El Auditor terminó con código inesperado: $auditExit"
        }
        if ($auditExit -eq 2) {
            Write-Warning "El Auditor se ejecutó correctamente, pero mantiene hallazgos pendientes."
        }
    }
    finally {
        Pop-Location
    }
}

Write-Host "`nSPB-003.2-B1.3 aplicado." -ForegroundColor Green
Write-Host "Respaldo: $backupRoot"
Write-Host "Manifiesto: $manifestPath"
